// One row per keyword and week. The whole timeline is written every run (update by key), because Google
// rescales each request: rewriting the series keeps every value of a keyword on the scale of the latest run.
const out = [];
const updatedAt = new Date().toISOString();
for (const item of $input.all()) {
  const r = item.json;
  if (r.rowType !== 'trend' || !r.searchTerm) continue;
  const geo = r.geo || 'worldwide';
  for (const p of r.interestOverTime_timelineData ?? []) {
    const week = new Date(Number(p.time) * 1000).toISOString().slice(0, 10);
    out.push({
      json: {
        key: `${week}|${r.searchTerm}|${geo}`,
        week,
        keyword: r.searchTerm,
        geo,
        interest: p.value?.[0] ?? '',
        partial: p.isPartial === true,
        scale: r.scale?.method ?? '',
        updatedAt,
      },
    });
  }
}
return out;
